public class InstrumentedChatService
{
    private readonly TelemetryClient _telemetry;
    private readonly IChatClient _chatClient;
    private static readonly Dictionary<string, (double input, double output)> TokenCosts =
        new() { ["gpt-4o"] = (0.000003, 0.000006), ["gpt-4o-mini"] = (0.00000015, 0.0000006) };

    public async Task<string> GenerateAsync(
        string prompt, string model = "gpt-4o", [CallerMemberName] string operation = "")
    {
        var stopwatch = Stopwatch.StartNew();

        var response = await _chatClient.CompleteAsync(
            new ChatMessage[] { new(ChatRole.User, prompt) },
            new() { ModelId = model });

        stopwatch.Stop();
        var usage = response.Usage;

        var inputCost = usage.InputTokenCount * TokenCosts[model].input;
        var outputCost = usage.OutputTokenCount * TokenCosts[model].output;
        var totalCost = inputCost + outputCost;

        // Record custom metrics
        _telemetry.GetMetric("ai.tokens.total").Track(
            usage.InputTokenCount + usage.OutputTokenCount,
            new Dictionary<string, string>
            {
                ["model"] = model,
                ["operation"] = operation,
                ["user_id"] = GetCurrentUserId()
            });

        _telemetry.GetMetric("ai.cost_usd").Track(totalCost,
            new Dictionary<string, string> { ["model"] = model });

        _telemetry.GetMetric("ai.llm_duration_ms").Track(stopwatch.ElapsedMilliseconds);

        // Track hallucination rate via automated checks
        var groundedness = await CheckGroundednessAsync(prompt, response.Text);
        _telemetry.GetMetric("ai.hallucination_rate").Track(groundedness ? 0 : 1);

        return response.Text;
    }
}
